/**
 * One scenario per check of debtor-chasing-build-standard, for Payment Watch.
 *
 * Generated by `npx @aipathway/conformance init debtor-chasing-build-standard`,
 * then written for this build. The checks are fetched at run time from
 * https://aipathway.com.au/explore-ai/debtor-chasing-build-standard; this file
 * is the world each check starts in, how the build is driven, and what "held"
 * means. Every holds reads the world the build wrote into, never the build.
 *
 * The runner owns the clock: 2026-09-21T04:00Z is 2pm in Brisbane, a Monday.
 * Money is in cents.
 */

import { DebtorWorld } from "@aipathway/conformance";

const BUCKETS = ["just_late", "drifting", "hard", "broken_promise"];
const HOUR = 3_600_000;
const DAY = 24 * HOUR;

const client = (id, extra = {}) => ({ id, name: `Client ${id}`, timezone: "Australia/Brisbane", ...extra });
const inv = (id, customerId, amount, dueAt, extra = {}) => ({
  id,
  customerId,
  amount,
  issuedAt: extra.issuedAt ?? "2026-06-01",
  dueAt,
  ...extra,
});

const ready = (world, customerId) =>
  world.escalations.filter((e) => e.reason === "debtor.reminder_ready_for_release" && (e.detail ?? "").startsWith(`${customerId} `));
const entryFor = (run, customerId) => run.filter((e) => e.customerId === customerId);
const dialled = (world, customerId) => world.dials.some((d) => d.customerId === customerId);
const portCalls = (world, port) => world.calls.filter((c) => c.port === port);

export const scenarios = [
  {
    checkId: "coverage-measured",
    // 1. Not a software check. The business attaches its own measured, dated
    // share of the overdue book it can reach; this build never scores it.
    world: () => new DebtorWorld(),
    drive: () => {},
    holds: () => false,
    describe: () =>
      "Not measured by this build. The business running Payment Watch attaches the share of its overdue book with a reachable contact, and the date it was taken.",
  },
  {
    checkId: "overdue-off-due-date",
    // 2. Issued long ago with a due date still ahead: not in the run.
    world: () =>
      new DebtorWorld({
        customers: [client("A"), client("B"), client("C")],
        invoices: [
          inv("INV-A1", "A", 400_000, "2026-10-15", { issuedAt: "2026-05-01" }),
          inv("INV-B1", "B", 120_000, "2026-09-14", { issuedAt: "2026-09-10" }),
          inv("INV-C1", "C", 80_000, "2026-08-01", { issuedAt: "2026-07-01" }),
        ],
      }),
    drive: (build, world) => build(world.ports()),
    holds: (world) => {
      const run = world.lastRun;
      const ids = run.flatMap((e) => e.invoiceIds);
      const due = { "INV-A1": "2026-10-15", "INV-B1": "2026-09-14", "INV-C1": "2026-08-01" };
      return (
        world.runs.length === 1 &&
        !ids.includes("INV-A1") &&
        ids.includes("INV-B1") &&
        ids.includes("INV-C1") &&
        ids.every((id) => due[id] < "2026-09-21")
      );
    },
    describe: (world) => `run: ${JSON.stringify(world.lastRun.map((e) => e.invoiceIds))}`,
  },
  {
    checkId: "four-buckets",
    // 3. One row per bucket: 5 days late, 25 days, 82 days, and a promise that passed.
    world: () =>
      new DebtorWorld({
        customers: [client("JL"), client("DR"), client("HD"), client("BP")],
        invoices: [
          inv("INV-JL", "JL", 50_000, "2026-09-16"),
          inv("INV-DR", "DR", 50_000, "2026-08-27"),
          inv("INV-HD", "HD", 50_000, "2026-07-01"),
          inv("INV-BP", "BP", 50_000, "2026-09-10"),
        ],
        promises: [{ customerId: "BP", date: "2026-09-15", amount: 50_000, capturedAt: "2026-09-11T01:00:00.000Z" }],
      }),
    drive: (build, world) => build(world.ports()),
    holds: (world) => {
      const want = { JL: "just_late", DR: "drifting", HD: "hard", BP: "broken_promise" };
      const run = world.lastRun;
      return (
        Object.entries(want).every(([id, b]) => {
          const rows = entryFor(run, id);
          return rows.length === 1 && rows[0].bucket === b;
        }) && run.every((e) => BUCKETS.includes(e.bucket))
      );
    },
    describe: (world) => `buckets: ${JSON.stringify(world.lastRun.map((e) => [e.customerId, e.bucket]))}`,
  },
  {
    checkId: "broken-promise-outranks",
    // 4. A $300 broken promise against a $20,000 invoice merely late.
    world: () =>
      new DebtorWorld({
        customers: [client("SMALL"), client("BIG")],
        invoices: [inv("INV-S", "SMALL", 30_000, "2026-09-05"), inv("INV-L", "BIG", 2_000_000, "2026-08-20")],
        promises: [{ customerId: "SMALL", date: "2026-09-18", amount: 30_000, capturedAt: "2026-09-08T01:00:00.000Z" }],
      }),
    drive: (build, world) => build(world.ports()),
    holds: (world) => {
      const order = world.lastRun.filter((e) => !e.excludedReason).map((e) => e.customerId);
      return order.length === 2 && order[0] === "SMALL" && order[1] === "BIG";
    },
    describe: (world) => `order: ${world.lastRun.map((e) => `${e.customerId}:${e.bucket}:${e.amount}`).join(", ")}`,
  },
  {
    checkId: "rank-by-amount-at-risk",
    // 5. Same bucket (drifting): older and small, newer and large; then a tie on
    // amount that only age may break.
    world: () =>
      new DebtorWorld({
        customers: [client("OLD"), client("NEW"), client("TIE-OLD"), client("TIE-NEW")],
        invoices: [
          inv("INV-O", "OLD", 50_000, "2026-08-10"),
          inv("INV-N", "NEW", 800_000, "2026-09-01"),
          inv("INV-TO", "TIE-OLD", 100_000, "2026-08-12"),
          inv("INV-TN", "TIE-NEW", 100_000, "2026-09-02"),
        ],
      }),
    drive: (build, world) => build(world.ports()),
    holds: (world) => {
      const order = world.lastRun.filter((e) => !e.excludedReason).map((e) => e.customerId);
      return (
        JSON.stringify(order) === JSON.stringify(["NEW", "TIE-OLD", "TIE-NEW", "OLD"]) &&
        world.lastRun.every((e) => e.bucket === "drifting")
      );
    },
    describe: (world) => `order: ${world.lastRun.map((e) => `${e.customerId}:${e.amount}`).join(", ")}`,
  },
  {
    checkId: "one-customer-one-conversation",
    // 6. Six overdue invoices on one client, plus one other client.
    world: () =>
      new DebtorWorld({
        customers: [client("SIX"), client("ONE")],
        invoices: [
          ...[1, 2, 3, 4, 5, 6].map((n) => inv(`INV-6${n}`, "SIX", 10_000 * n, `2026-09-0${n}`)),
          inv("INV-ONE", "ONE", 70_000, "2026-09-03"),
        ],
      }),
    drive: (build, world) => build(world.ports()),
    holds: (world) => {
      const rows = entryFor(world.lastRun, "SIX");
      const ids = [1, 2, 3, 4, 5, 6].map((n) => `INV-6${n}`);
      return (
        rows.length === 1 &&
        rows[0].amount === 210_000 &&
        rows[0].invoiceIds.length === 6 &&
        ids.every((id) => rows[0].invoiceIds.includes(id)) &&
        ready(world, "SIX").length <= 1
      );
    },
    describe: (world) => `SIX entries: ${JSON.stringify(entryFor(world.lastRun, "SIX"))}`,
  },
  {
    checkId: "relationship-balances-excluded",
    // 7. A$90,000 owed, far above the A$25,000 threshold, beside an ordinary client.
    world: () =>
      new DebtorWorld({
        customers: [client("ANCHOR"), client("SMALLER")],
        invoices: [inv("INV-AN", "ANCHOR", 9_000_000, "2026-08-15"), inv("INV-SM", "SMALLER", 60_000, "2026-09-05")],
      }),
    drive: (build, world) => build(world.ports()),
    holds: (world) => {
      const rows = entryFor(world.lastRun, "ANCHOR");
      const handed = world.escalations.filter(
        (e) => e.reason === "debtor.relationship_account" && (e.detail ?? "").includes("ANCHOR") && /Owner: \S/.test(e.detail ?? ""),
      );
      return (
        rows.length === 1 &&
        typeof rows[0].excludedReason === "string" &&
        rows[0].excludedReason.length > 0 &&
        handed.length === 1 &&
        ready(world, "ANCHOR").length === 0 &&
        !dialled(world, "ANCHOR") &&
        ready(world, "SMALLER").length === 1
      );
    },
    describe: (world) =>
      `ANCHOR: ${JSON.stringify(entryFor(world.lastRun, "ANCHOR"))}; escalations: ${world.escalations.map((e) => e.reason).join(", ")}`,
  },
  {
    checkId: "promise-is-an-object",
    // 8. The client replies on the reminder thread: "I'll pay Friday", no
    // figure, on an invoice already carrying a dispute.
    world: () =>
      new DebtorWorld({
        customers: [client("FRI")],
        invoices: [inv("INV-F1", "FRI", 150_000, "2026-08-30", { disputed: true })],
      }),
    drive: (build, world) =>
      build(world.ports(), {
        replies: [{ messageId: "msg-fri-1", invoiceId: "INV-F1", kind: "promise", date: "2026-09-25", amount: null }],
      }),
    holds: (world) => {
      const writes = portCalls(world, "record_promise");
      const stored = world.promises.filter((p) => p.customerId === "FRI");
      const after = world.ports().readLedger().find((i) => i.id === "INV-F1");
      return (
        writes.length === 1 &&
        writes[0].request.date === "2026-09-25" &&
        writes[0].request.amount === null &&
        typeof writes[0].response.capturedAt === "string" &&
        stored.length === 1 &&
        stored[0].amount === null &&
        after?.disputed === true &&
        ready(world, "FRI").length === 0
      );
    },
    describe: (world) => `record_promise: ${JSON.stringify(portCalls(world, "record_promise"))}`,
  },
  {
    checkId: "promised-date-is-followup",
    // 9. A promise for 2026-09-26, five days out, then a run on each of the next
    // four days. An ordinary client is in the book so every run has a row.
    world: () =>
      new DebtorWorld({
        customers: [client("WAIT"), client("OTHER")],
        invoices: [inv("INV-W", "WAIT", 300_000, "2026-08-20"), inv("INV-OT", "OTHER", 40_000, "2026-09-01")],
        promises: [{ customerId: "WAIT", date: "2026-09-26", amount: null, capturedAt: "2026-09-21T03:00:00.000Z" }],
      }),
    drive: async (build, world) => {
      for (let d = 1; d <= 4; d += 1) {
        world.advance(DAY);
        await build(world.ports());
      }
    },
    holds: (world) =>
      world.runs.length === 4 &&
      world.runs.every((run) => entryFor(run, "WAIT").length === 0 && entryFor(run, "OTHER").length === 1) &&
      ready(world, "WAIT").length === 0,
    describe: (world) => `runs: ${JSON.stringify(world.runs.map((r) => r.map((e) => e.customerId)))}`,
  },
  {
    checkId: "gate-under-ranking",
    // 10. The top-ranked client, three times: 8:30pm Friday in Brisbane; 2pm on
    // the Queensland King's Birthday (Mon 5 Oct 2026); then 2pm the next day,
    // with the payment applied in the ledger after the read and before the gate.
    world: () =>
      new DebtorWorld({
        now: new Date("2026-10-02T10:30:00.000Z"),
        holidays: ["2026-10-05"],
        customers: [client("TOP"), client("LOW")],
        invoices: [inv("INV-T1", "TOP", 1_800_000, "2026-09-01"), inv("INV-L1", "LOW", 20_000, "2026-09-20")],
      }),
    drive: async (build, world) => {
      await build(world.ports()); // Fri 2 Oct, 8:30pm local
      world.advance(2 * DAY + 17.5 * HOUR); // Mon 5 Oct, 2pm local, public holiday
      await build(world.ports());
      world.advance(DAY); // Tue 6 Oct, 2pm local
      const ports = world.ports();
      const gate = ports.gate;
      let paid = false;
      ports.gate = (customerId) => {
        if (!paid) {
          world.markPaid("INV-T1"); // the client paid; the ledger shows it before the gate is asked
          paid = true;
        }
        return gate(customerId);
      };
      await build(ports);
    },
    holds: (world) => {
      const top = world.gateDecisions.filter((g) => g.customerId === "TOP").map((g) => g.decision);
      const topFirst = world.runs.length === 3 && world.runs[0][0]?.customerId === "TOP" && world.runs[1][0]?.customerId === "TOP";
      return (
        topFirst &&
        top.length === 3 &&
        top.every((d) => d.allowed === false) &&
        top[0].reason === "outside_hours" &&
        top[1].reason === "public_holiday" &&
        top[2].reason === "already_paid" &&
        ready(world, "TOP").length === 0 &&
        !dialled(world, "TOP") &&
        world.overrides.length === 0
      );
    },
    describe: (world) => `gate: ${JSON.stringify(world.gateDecisions)}`,
  },
  {
    checkId: "exceptions-attributable",
    // 11. A row held at 8:30pm. The first exception.closed carries no named
    // approver; the second names one.
    world: () =>
      new DebtorWorld({
        now: new Date("2026-09-21T10:30:00.000Z"),
        customers: [client("HELD")],
        invoices: [inv("INV-H1", "HELD", 250_000, "2026-08-25")],
      }),
    drive: async (build, world) => {
      await build(world.ports(), { overrides: [{ customerId: "HELD", reason: "client asked for the statement tonight" }] });
      world.advance(5 * 60_000);
      await build(world.ports(), {
        overrides: [{ customerId: "HELD", reason: "client asked for the statement tonight", approver: "Sam Okafor" }],
      });
    },
    holds: (world) => {
      const o = world.overrides;
      const firstRunReady = world.escalations.findIndex((e) => e.reason === "debtor.override_refused");
      const readyIdx = world.escalations.findIndex((e) => e.reason === "debtor.reminder_ready_for_release");
      return (
        world.refusedOverrides.length === 1 &&
        o.length === 1 &&
        o[0].customerId === "HELD" &&
        o[0].approver === "Sam Okafor" &&
        o[0].reason.length > 0 &&
        typeof o[0].at === "string" &&
        firstRunReady >= 0 &&
        readyIdx > firstRunReady &&
        ready(world, "HELD").length === 1 &&
        (ready(world, "HELD")[0].detail ?? "").includes("Sam Okafor")
      );
    },
    describe: (world) => `overrides: ${JSON.stringify(world.overrides)}; refused: ${JSON.stringify(world.refusedOverrides)}`,
  },
];

// The check a stub cannot pass, and is not asked to: a real ledger, a real
// clock and a real number. It runs with the hosted provider (Get Paid on
// Office Voice). Payment Watch never dials, so it is not written here.
export const liveScenarios = [
  {
    checkId: "pass-test",
    world: () => new DebtorWorld(),
    drive: () => {},
    holds: () => false,
    describe: () => "Runs with the hosted provider on a live ledger and a real number. Not built here.",
  },
];
